import React, { useEffect, useState } from 'react';
import { FaCheckCircle } from 'react-icons/fa';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import ZoomSubs from '../components/modal/ZoomSubs';
import { useAppContext } from '../contextApi/AppContext';

const ProductPostedSuccess = () => {
  const {userData, packagesList, getUserplan} = useAppContext()
  const location = useLocation();
  const navigate = useNavigate();
  const searchParams = new URLSearchParams(location.search);
  const serializedData = searchParams.get('data');
  const data = serializedData ? JSON.parse(decodeURIComponent(serializedData)) : null;
  const [showModal, setShowModal] = useState(false);


const filteredPackages = packagesList?.filter(
  (item) => item.type === "Zoom"
);

const membership_id = userData?.membership_details?.find((data) => data.membership_id === filteredPackages[0]?._id )

  useEffect(() => {
    if(data?.category_id === '6548c04e1e40c887cc280d07' ){
      if(membership_id?.membership_status === 'Active'){
        setShowModal(false);
      }else{
        const timer = setTimeout(() => {
          setShowModal(true);
        }, 1000);
        return () => clearTimeout(timer); 

      }
    }
    // eslint-disable-next-line
  }, [membership_id, filteredPackages]); 

  useEffect(() => {
    getUserplan()
    // eslint-disable-next-line
  },[ ])

  useEffect(() => {
    if (data === null) {
      navigate(-1);
    }
  }, [data, navigate]);

  return (
    <div className="container d-flex justify-content-center mt-1" style={{ minHeight: '100vh' }}>
      <div className="card text-center border-0 shadow-lg" style={{ borderRadius: '15px', width: '100%', maxWidth: '600px' }}>
        <div className="card-body p-5">
          <FaCheckCircle className="text-success mb-2" size={80} />
          <h1 className="card-title text-success fw-bold">Success!</h1>
          <p className="card-text lead text-muted">Your product has been successfully posted.</p>
          <div className="product-summary mt-2">
            <h4 className="fw-bold">Product Summary</h4>
            <p className="text-muted"><strong>Name:</strong> {data?.title}</p>
            <p className="text-muted"><strong>Price:</strong> {data?.product_price || 'N/A'}</p>
            <p className="text-muted"><strong>Description:</strong> {data?.description?.split(" ").slice(0, 10).join(" ")}{data?.description?.split(" ").length > 10 ? "..." : ""}</p>
          </div>
          <div className="d-flex justify-content-center mt-4">
          {membership_id?.membership_status === 'Active' ? (
            <button onClick={() => navigate('/my-post')} className="btn btn-outline-success btn-lg mx-2" style={{ borderRadius: '30px' }}> Check Your Post</button>
          ) : (
            <button onClick={() => setShowModal(true)} className="btn btn-outline-success btn-lg mx-2" style={{ borderRadius: '30px' }}> Subscribe to Zoom</button>
          ) } 
            <Link to="/" className="btn btn-outline-secondary btn-lg mx-2" style={{ borderRadius: '30px' }}>Back to Homepage</Link>
          </div>
        </div>
      </div>

      <ZoomSubs showModal={showModal} setShowModal={setShowModal} /> 
    </div>
  );
}

export default ProductPostedSuccess;
