import React from "react";
import { Link } from "react-router-dom";
import { useAppContext } from "../../contextApi/AppContext";

const ProductFilter = ({ onFilter }) => {
  const { filterAttributeList } = useAppContext();

  return (
    <>
      <nav className="navbar navbar-expand-lg bg-body-tertiary sideBarNav text14">
        <div
          className="titelBx"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#sideBarCollapse"
          aria-controls="sideBarCollapse">
          <Link
            className="navbar-brand"
            to="#sideBarCollapse"
            type="button"
            data-bs-toggle="collapse"
            data-bs-target="#sideBarCollapse"
            aria-controls="sideBarCollapse"
          >
            Short By Filter
          </Link>
          <i
            className="navbar-toggler"
          >
            <span className="fa fa-chevron-down" />
          </i>
        </div>
        <div className="collapse navbar-collapse" id="sideBarCollapse">
          <div className="customeSidebar">
            {Array.isArray(filterAttributeList) &&
              filterAttributeList.map((item) => {
                const value =
                  Array.isArray(item.options) && item.options.length > 0
                    ? item.options
                    : Array.isArray(item.attribute_values) &&
                      item.attribute_values.length > 0
                      ? item.attribute_values
                      : null;

                return (
                  <div key={item._id}>
                    {value && value.length > 0 && (
                      <div>
                        <div className="headBx" key={item._id}>
                          {item.attribute}
                        </div>
                        <div className="listBx p0">
                          {value.map((attribute) => (
                            <ul
                              className="list-group list-group-flush"
                              key={attribute._id}
                            >
                              <li className="list-group-item d-flex justify-content-between align-items-start">
                                <label>
                                  <input
                                    type="checkbox"
                                    onChange={(e) => {
                                      onFilter(
                                        e,
                                        item.attribute,
                                        attribute.value
                                      );
                                    }}
                                  />{" "}
                                  {attribute.value}
                                </label>
                              </li>
                            </ul>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            {/* <div className="headBx">Experience</div>
          <div className="listBx">
            <input
              type="range"
              defaultValue={200}
              min={0}
              max={1000}
              className="width100 mt10 mb10"
            />
          </div> */}
          </div>
        </div>
      </nav>
    </>
  );
};

export default ProductFilter;
