import React, { useEffect, useState } from "react";
import Ads from "./../components/comon/Ads";
import { Link, useLocation, useNavigate, useParams } from "react-router-dom";
import CallAction from "../components/comon/CallAction";
import { useAppContext } from "../contextApi/AppContext";
import { toast } from "react-toastify";
import JobApply from "../components/modal/JobApply";

const JobDetail = ({ initialDetail }) => {
  const {
    getJobListDetail,
    jobDetail,
    setJobDetail,
    getJobList,
    getReletedProduct,
    isLogIn,
    reletedList,
    jobList,
    userData,
    wishListAdd,
    productrating,
    getreviews,
    reviews,
  } = useAppContext();
  const { id } = useParams();
  const location1 = useLocation();
  const [showModal, setShowModal] = useState(false);
  const navigate = useNavigate();

  const [rating, setRating] = useState(0);
  const [review, setReview] = useState("");
  const [images, setImages] = useState([]);
  const [previewImages, setPreviewImages] = useState([]);

  const handleRatingChange = (newRating) => {
    setRating(newRating);
    // console.log('New rating set:', rating);
  };

  const handleReviewChange = (event) => {
    setReview(event.target.value);
  };

  const handleImageChange = (event) => {
    const files = Array.from(event.target.files);
    setImages(files);
    setPreviewImages(files.map((file) => URL.createObjectURL(file)));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const formData = new FormData();
    formData.append("productId", product_id);
    formData.append("rating", rating);
    formData.append("review", review);
    images.forEach((image, index) => {
      formData.append(`attachments[${index}]`, image);
    });

    productrating(formData);
  };

  useEffect(() => {
    const fetchData = async () => {
      await getJobListDetail(id);
    };
    if (!initialDetail && id) {
      fetchData();
    }
    if (!!initialDetail && !!initialDetail.data && !!initialDetail.data._id) {
      setJobDetail(initialDetail);
    }
    // eslint-disable-next-line
  }, [id, initialDetail]);

  useEffect(() => {
    const fetchData = async () => {
      await getJobList(id);
    };
    fetchData();
    // eslint-disable-next-line
  }, [id]);

  const {
    description,
    title,
    attribute_values,
    createdAt,
    category_id,
    category_name,
    category_slug,
    product_id,
    sub_category_id,
    userId,
    _id,
    JobApplied,
    company_logo,
  } = jobDetail.data || {};

  useEffect(() => {
    if (product_id) {
      getreviews(product_id);
    }
  }, [product_id]);

  const getAttributeValue = (attributeName) => {
    if (!Array.isArray(attribute_values)) return null;
    const attribute = attribute_values.find(
      (item) => item.attribute === attributeName
    );
    if (attribute) {
      return attribute.value;
    } else {
      return null;
    }
  };
  const location = getAttributeValue("Location");
  const experience = getAttributeValue("Experience");
  const salary = getAttributeValue("Salary");
  const companyName = getAttributeValue("Company Name");

  const formatDuration = (createdAt) => {
    const now = new Date();
    const createdDate = new Date(createdAt);
    const diff = now - createdDate;

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

    if (days > 1) {
      return `${days} days`;
    } else {
      return `${hours} hours, ${minutes} minutes`;
    }
  };
  const formattedDuration = formatDuration(createdAt);

  useEffect(() => {
    if (product_id && category_id) {
      getReletedProduct(category_id, sub_category_id, product_id);
    }
    // eslint-disable-next-line
  }, [product_id, category_id, sub_category_id]);

  const handleShowModal = () => {
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const redirect = (path) => {
    if (isLogIn) {
      navigate(path);
    } else {
      toast("please Login first");
      setTimeout(() => {
        navigate(`/login?redirect=${location1.pathname}`);
      }, 1000);
    }
  };

  const postWishlist = (e) => {
    e.preventDefault(); // Prevent the default link behavior
    wishListAdd(jobDetail?.data.product_id);
  };

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-12">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li>
                  <Link to={`/${category_slug}?category_id=${category_id}`}>
                    {category_name}
                  </Link>
                </li>
                <li className="active">Detail Page Of {title}</li>
              </ul>
            </div>
          </aside>
        </article>
      </section>
      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
            {/* job deatils part start */}
            {jobDetail.isLoad && (
              <div className="col-md-10 d-flex justify-content-center ">
                <div className="spinner-grow text-info my-4" role="status">
                  <span className="sr-only">Loading...</span>
                </div>
              </div>
            )}
            {!jobDetail.isLoad && (
              <div className="col-md-6">
                <div className="card jobeItem mb20">
                  <div className="card-body">
                    <div className="row">
                      <div className="col-md-9 col-sm-12">
                        <h5>{title}</h5>
                        <h6 className="reviewList">
                          <b>
                            <i className="fa-solid fa-location-crosshairs mx-2">
                              {" "}
                            </i>
                            {companyName || ""}
                          </b>
                        </h6>
                      </div>
                      <div className="col-md-3 col-sm-12 logoBx">
                        <Link
                          to={`/seller-info/${jobDetail?.data.seller_details?._id}`}
                        >
                          <img
                            src={company_logo}
                            width={44}
                            className="mt5"
                            alt=""
                          />
                        </Link>
                      </div>
                    </div>
                    <ul className="list-inline divider mb5">
                      <li>
                        <i className="fa fa-briefcase" /> {experience || ""}
                      </li>
                      <li>
                        <i className="fa fa-inr" /> {salary || "Not Disclosed"}
                      </li>
                      <li>
                        <i className="fa fa-map-marker" />{" "}
                        {location || "Not Mentioned"}
                      </li>
                    </ul>
                    <hr />
                    <div className="row">
                      <div className="col-md-7 d-flex justify-content-between">
                        <p className="mt5 mb5 text16">
                          <b>Posted :</b> {formattedDuration} ago
                        </p>
                        {userData._id === userId ? (
                          " "
                        ) : (
                          <div>
                            {!isLogIn ? (
                              <>
                                <button
                                  onClick={() => redirect("/message")}
                                  className="btn btn-primary text-white"
                                >
                                  Login to Apply
                                </button>
                              </>
                            ) : (
                              <>
                                <button
                                  type="button"
                                  className="btn btn-primary px-3 text-white"
                                  onClick={handleShowModal}
                                  disabled={JobApplied}
                                >
                                  {JobApplied ? "Applied" : "Apply"}
                                </button>
                                &nbsp;&nbsp;
                                <button
                                  type="button"
                                  className="btn btn-primary px-3 text-white"
                                  onClick={postWishlist}
                                >
                                  {" "}
                                  <i
                                    className="fa fa-bookmark-o "
                                    style={{ marginRight: "5px" }}
                                  />
                                  save
                                </button>
                                <JobApply
                                  showModal={showModal}
                                  title={title}
                                  handleCloseModal={handleCloseModal}
                                  id={_id}
                                />
                              </>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
                <div className="card mb20">
                  <div className="card-body">
                    <h5>Job description</h5>
                    <p>{description} </p>
                    <hr />
                    {Array.isArray(attribute_values) &&
                      attribute_values.map((item) => (
                        <p key={item._id}>
                          <b>{item.attribute} : </b>
                          {item.value}
                        </p>
                      ))}
                  </div>
                </div>
              </div>
            )}

            {/* job deatils part end */}
            {/* interested job part start */}
            <div className="col-md-4">
              {/* {userData._id === userId ? (
                ""
              ) : (
                <CallAction details={jobDetail?.data} productId={product_id} />
              )} */}
              <div className="card">
                <div className="card-body">
                  <h5>
                    <b>Similar jobs</b>
                  </h5>
                  <hr />
                  {Array.isArray(reletedList) &&
                    reletedList.map((item) => {
                      const getAttributeValue = (attributeName) => {
                        if (!Array.isArray(jobList)) return null;

                        const matchingJob = jobList?.find(
                          (job) => job?.product_id === item._id
                        );
                        if (!matchingJob) return null;

                        const attribute_values = matchingJob?.attribute_values;
                        const attribute = attribute_values?.find(
                          (item) => item.attribute === attributeName
                        );
                        return attribute ? attribute?.value : null;
                      };

                      const location = getAttributeValue("Location");
                      const salary = getAttributeValue("Salary");
                      const companyName = getAttributeValue("Company Name");

                      const formatDuration = (createdAt) => {
                        const now = new Date();
                        const createdDate = new Date(createdAt);
                        const diff = now - createdDate;

                        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
                        const hours = Math.floor(
                          (diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)
                        );
                        const minutes = Math.floor(
                          (diff % (1000 * 60 * 60)) / (1000 * 60)
                        );

                        if (days > 1) {
                          return `${days} days`;
                        } else {
                          return `${hours} hours, ${minutes} minutes`;
                        }
                      };
                      const formattedDuration = formatDuration(item.createdAt);
                      return (
                        <Link
                          to={`/product/related-product/${item._id}`}
                          className="jobeItem"
                          key={item._id}
                        >
                          <div className="row">
                            <div className="col-md-9 col-sm-12">
                              <h5>{item.title}</h5>
                              <ul className="reviewList mb5">
                                <li>
                                  <b>{companyName}</b>
                                </li>
                                <li className="text-muted">|</li>
                              </ul>
                            </div>
                            <div className="col-md-3 col-sm-12 logoBx">
                              <img
                                src="assets/images/g-logo.png"
                                width={44}
                                className="mt5"
                                alt=""
                              />
                            </div>
                          </div>
                          <ul className="list-inline divider mb5">
                            <li>
                              <i className="fa fa-map-marker" /> {location}
                            </li>
                            <li>
                              <i className="fa fa-map-marker" /> {salary}
                            </li>
                            <li>
                              <b>Posted : </b>
                              <span className="text-muted">
                                {formattedDuration}{" "}
                              </span>
                            </li>
                          </ul>
                          <hr />
                        </Link>
                      );
                    })}
                  <div align="center">
                    <Link
                      className="btn btn-primary"
                      to={`/${category_slug}?category_id=${category_id}`}
                    >
                      View all
                    </Link>
                  </div>
                </div>
              </div>
              <div className="col-md-12 mt10">
                <div className="card">
                  <div className="card-header">
                    <h4>Rate this product:</h4>
                  </div>
                  <div className="card-body">
                    <div className="rating mt-4">
                      {[...Array(5)].map((star, index) => (
                        <button
                          key={index}
                          type="button"
                          className={`btn btn-link ${
                            index < rating ? "text-warning" : ""
                          }`}
                          onClick={() => handleRatingChange(index + 1)}
                        >
                          <i className="fas fa-star"></i>
                        </button>
                      ))}
                    </div>
                    <form onSubmit={handleSubmit} className="mt-4">
                      <div className="form-group">
                        <label htmlFor="review">Review:</label>
                        <textarea
                          id="review"
                          className="form-control"
                          value={review}
                          onChange={handleReviewChange}
                        ></textarea>
                      </div>
                      <div className="form-group mt-3">
                        <label htmlFor="images">Upload Images:</label>
                        <input
                          type="file"
                          id="images"
                          className="form-control"
                          multiple
                          onChange={handleImageChange}
                        />
                        <div className="preview-images mt-3">
                          {previewImages.map((src, index) => (
                            <img
                              key={index}
                              src={src}
                              alt="Preview"
                              className="img-thumbnail mr-2"
                              style={{ width: "100px", height: "100px" }}
                            />
                          ))}
                        </div>
                      </div>
                      <button type="submit" className="btn btn-primary mt-3">
                        Submit Review
                      </button>
                    </form>
                  </div>
                </div>

                {Array.isArray(reviews?.data) && reviews?.data ? (
                  <div className="mt-5">
                    <h4>Reviews:</h4>
                    {Array.isArray(reviews.data) &&
                      reviews?.data?.map((review) => (
                        <div className="card mb-3 shadow-sm" key={review._id}>
                          <div className="card-body">
                            <div className="d-flex align-items-center mb-3">
                              <img
                                src={review.user_img}
                                alt="User"
                                className="rounded-circle mr-3"
                                style={{ width: "50px", height: "50px" }}
                              />
                              <div>
                                <div
                                  className="user-pofileinfo"
                                  style={{ marginLeft: "10px" }}
                                >
                                  <h6 className="mb-0">{review.user_name}</h6>
                                  <small className="text-muted">
                                    {new Date(
                                      review.createdAt
                                    ).toLocaleDateString()}
                                  </small>
                                </div>
                              </div>
                            </div>
                            <div className="rating">
                              {[...Array(5)].map((star, index) => (
                                <i
                                  key={index}
                                  className={`fas fa-star ${
                                    index < review.rating
                                      ? "text-warning"
                                      : "text-secondary"
                                  }`}
                                ></i>
                              ))}
                            </div>
                            <p className="mt-3">{review.review}</p>
                            <div className="mt-3">
                              {review.attachments.map((src, index) => (
                                <img
                                  key={index}
                                  src={src}
                                  alt="Review attachment"
                                  className="img-thumbnail mr-2 mb-2"
                                  style={{ width: "100px", height: "100px" }}
                                />
                              ))}
                            </div>
                          </div>
                        </div>
                      ))}
                  </div>
                ) : (
                  <div> No Reviws Found</div>
                )}
              </div>
            </div>

            {/* interested job part end */}
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
          </article>
        </article>
      </section>
    </>
  );
};

export default JobDetail;
