import React from 'react'
import { Link } from 'react-router-dom'
import { useAppContext } from '../../contextApi/AppContext';

const RealstateFilter = ({ onFilter }) => {
  const { filterAttributeList } = useAppContext();

  return (
    <>
      <nav className="navbar navbar-expand-lg bg-body-tertiary sideBarNav text14">
        <div
          className="titelBx"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#sideBarCollapse"
          aria-controls="sideBarCollapse">
          <Link
            className="navbar-brand"
            to="#sideBarCollapse"
            type="button"
            data-bs-toggle="collapse"
            data-bs-target="#sideBarCollapse"
            aria-controls="sideBarCollapse"
          >
            Short By Filter
          </Link>
          <i
            className="navbar-toggler"
          >
            <span className="fa fa-chevron-down" />
          </i>
        </div>
        <div className="collapse navbar-collapse" id="sideBarCollapse">
          <div className="customeSidebar">
            {Array.isArray(filterAttributeList) && filterAttributeList.map((item) => {
              const value = Array.isArray(item.options) && item.options.length > 0 ? item.options : Array.isArray(item.attribute_values) && item.attribute_values.length > 0 ? item.attribute_values : null
              return (
                <div key={item._id}>
                  <div className="headBx">{item.attribute}</div>
                  <div className="listBx">
                    <select
                      name="status"
                      className="form-control"
                      title="Status"
                      onChange={(e) => {
                        onFilter(e, item.attribute)
                      }}
                    >
                      <option value="any">Any</option>
                      {Array.isArray(value) && value.map((attribute) => (
                        <option value={attribute.value} key={attribute._id}>{attribute.value}</option>
                      ))}
                    </select>
                  </div>
                </div>
              )
            })}
            {/* <div className="headBx">Similar category</div>
            <div className="listBx p0">
              <div className="list-group round0">
                <Link className="list-group-item d-flex justify-content-between align-items-center">
                  Freelancer
                  <span className="badge bg-primary rounded-pill">
                    92
                  </span>
                </Link>
                <Link className="list-group-item d-flex justify-content-between align-items-center">
                  Jobs
                  <span className="badge bg-primary rounded-pill">
                    56
                  </span>
                </Link>
                <Link className="list-group-item d-flex justify-content-between align-items-center">
                  Realestate
                  <span className="badge bg-primary rounded-pill">
                    42
                  </span>
                </Link>
                <Link className="list-group-item d-flex justify-content-between align-items-center">
                  Lessons &amp; Courses
                  <span className="badge bg-primary rounded-pill">
                    30
                  </span>
                </Link>
              </div>
            </div> */}
          </div>
        </div>
      </nav>
    </>
  )
}

export default RealstateFilter