import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { useAppContext } from '../../contextApi/AppContext'
import noPostar from '../../assets/no-poster.png'



const Product = ({ item }) => {
  const { goodsList, wishListAdd, wishListRemove, userData } = useAppContext()
  const [colorMap, setColorMap] = useState([]);


  const addWhishlist = (id) => {
    if (colorMap[id]) {
      wishListRemove(id);
      const filtered = { ...colorMap }
      filtered[id] = false
      setColorMap(filtered)
    } else {
      wishListAdd(id);
      setColorMap((prevColorMap) => ({
        ...prevColorMap,
        [id]: !prevColorMap[id],
      }));
    }
  };

  useEffect(() => {
    if (goodsList && Array.isArray(goodsList)) {
      let check = {}
      goodsList.forEach((list) => {
        check[list.product_id] = list.isWishlist
      })
      setColorMap(check)
    }
  }, [goodsList])

  return (
    <>
      <div className="col-md-3 col-12 proBx" key={item._id}>
        <div className="card mb-3" >
          <div className="imgBx" >
            <Link to={`/product-detail/${item._id}`} >
              <img
                src={item.photo || noPostar}
                className="card-img-top allImg"
                alt=""
              />
            </Link>
            {item.userId === userData._id ? '' : (
              <div
                className="iconWish"
                onClick={() => addWhishlist(item.product_id)}
              >
                <i
                  className={
                    (colorMap[item.product_id])
                      ? "fa fa-heart text-danger"
                      : "fa fa-heart-o"
                  }
                />
              </div>
            )}
          </div>
          <div className="card-body">
            <h5 className="card-title">
              <Link to={`/product-detail/${item._id}`}>
                {item?.title}
              </Link>
            </h5>
            <p style={{ overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical" }}>{item.description}</p>
          </div>
        </div>
      </div>
    </>
  )
}

export default Product