import React, { useState } from "react";
import { useAppContext } from "../../contextApi/AppContext";
import { IoIosClose } from "react-icons/io";

const JobApply = ({ showModal, title, handleCloseModal, id }) => {
  const { userData, jobApply } = useAppContext();
  const { email: initialEmail, mobile: initialMobile, name: initialName,
  } = userData || {};
  const [updatedName, setUpdatedName] = useState(initialName);
  const [updatedEmail, setUpdatedEmail] = useState(initialEmail);
  const [updatedMobile, setUpdatedMobile] = useState(initialMobile);
  const [resumeFile, setResumeFile] = useState(null);


  const handleNameChange = (event) => {
    setUpdatedName(event.target.value);
  };

  const handleEmailChange = (event) => {
    setUpdatedEmail(event.target.value);
  };

  const handleMobileChange = (event) => {
    setUpdatedMobile(event.target.value);
  };

  const handleFileChange = (event) => {
    setResumeFile(event.target.files[0]);
  };

  const handleSubmit = () => {
    const formData = new FormData();
    formData.append("name", updatedName);
    formData.append("email", updatedEmail);
    formData.append("mobile", updatedMobile);
    formData.append("file", resumeFile);
    formData.append("job_id", id);
    jobApply(formData);
    if (updatedName && updatedEmail && updatedMobile && resumeFile) {
      handleCloseModal();
    }
  }

  return (
    <>
      {showModal && (
        <div
          className="modal fade show"
          style={{ display: "block" }}
          id="exampleModal"
          tabIndex="-1"
          role="dialog"
          aria-labelledby="exampleModalLabel"
          aria-hidden="true"
        >
          <div
            className="modal-dialog modal-lg modal-dialog-centered"
            role="document"
          >
            <div className="modal-content shadow-lg border-0">
              <div className="modal-header bg-primary text-white">
                <h5 className=" modal-titled-flex d-flex justify-content-between align-items-center w-100" id="exampleModalLabel">
                  <span className="font-weight-bold"> Apply for {title}</span>
                  <span className="font-weight-bold" onClick={handleCloseModal} type='button' >
                    <IoIosClose />
                  </span>
                </h5>
              </div>
              <div className="modal-body">
                <div className="container">
                  <div className="row justify-content-center">
                    <div className="col-lg-9">
                      <div className="card border-0">
                        <div className="card-body">
                          <div className="mb-4">
                            <label className="mb10 " style={{ fontWeight: 'bold' }}> Enter Full Name :</label>
                            <input
                              type="text"
                              className="form-control form-control-lg rounded-3"
                              placeholder="Full Name"
                              value={updatedName}
                              onChange={handleNameChange}
                              required
                            />
                          </div>
                          <div className="mb-4">
                            <label className="mb10 " style={{ fontWeight: 'bold' }}> Email :</label>
                            <input
                              type="email"
                              className="form-control form-control-lg rounded-3"
                              placeholder="Email Address"
                              value={updatedEmail}
                              onChange={handleEmailChange}
                              required
                            />
                          </div>
                          <div className="mb-4">
                            <label className="mb10 " style={{ fontWeight: 'bold' }}> Number :</label>
                            <input
                              type="number"
                              className="form-control form-control-lg rounded-3"
                              placeholder="Number "
                              value={updatedMobile}
                              onChange={handleMobileChange}
                              required
                            />
                          </div>
                          <div className="mb-4">
                            <label className="mb10 " style={{ fontWeight: 'bold' }}> Upload CV/Resume  :</label>
                            <input
                              className="form-control form-control-lg rounded-3"
                              id="formFileLg"
                              type="file"
                              onChange={handleFileChange}
                              required
                            />
                            <div className="small text-muted mt-2">
                              Upload your CV/Resume or any other relevant file.
                              Max file size 50 MB
                            </div>
                          </div>
                          <div className="text-center">
                            <button
                              type="submit"
                              onClick={handleSubmit}
                              className="btn btn-primary btn-lg text-white"
                            >
                              Send Application
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default JobApply;
