import axios from "axios";
import { useEffect, useMemo } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import { useAppContext } from "../../contextApi/AppContext";

export const StripeResponse = () => {
  const { baseURL } = useAppContext();
  const location = useLocation();
  const {id} = useParams()
  const navigate = useNavigate();
  const token = useMemo(() => localStorage.getItem("token1"), []);

  const params = useMemo(() => new URLSearchParams(location.search), [location.search]);
  const session = useMemo(() => params.get("session_id"), [params]);
  const type = useMemo(() => params.get("type"), [params]);

  const verifyPayment = async () => {
    try {
      console.log('Verifying payment with session:', session);
      const { data } = await axios.post(
        `${baseURL}/api/subscription/session/verify`,
        { id: session },
        {
          headers: {
            token: token,
          },
        }
      );

      if (data.status === 200) {
        toast.success(data.message);
        navigate(`/learn/welcome?courseId=${id}`, {replace: true})
      } else {
        toast.error(data.message);
        navigate("/", {replace: true});
      }
    } catch (error) {
      navigate("/", {replace: true});
      toast.error(error?.response?.data?.message || error?.message);
    }
  };

  const verifyMembership = async () => {
    try {
      console.log('Verifying payment with session:', session);
      const { data } = await axios.post(
        `${baseURL}/api/membership/session/verify`,
        { id: session },
        {
          headers: {
            token: token,
          },
        }
      );
      if (data.status === 200) {
        toast.success(data.message);
        const serializedData = encodeURIComponent(JSON.stringify(data.data));
        navigate(`/payment-success?data=${serializedData}`, {replace: true})
      } else {
        toast.error(data.message);
        navigate("/", {replace: true});
      }
    } catch (error) {
      navigate("/", {replace: true});
      toast.error(error?.response?.data?.message || error?.message);
    }
  };

  useEffect(() => {
    if (session && token && id) {
      if(type !== 'membership'){
        verifyPayment();
      }else{
        verifyMembership()
      }
    }
    return () => { };
    // eslint-disable-next-line
  }, [session, token, id, type]);

  return null; // can show some loader or anything
};