import React from "react";
import { Link, useLocation } from "react-router-dom";
import { useAppContext } from "../../contextApi/AppContext";
import profile from "./../../assets/assets/images/user.jpg";

const AccountSideBar = ({ preview }) => {
  const { userData, LogOut } = useAppContext();
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const show_profile = searchParams.get("show_profile");
  const { image, name } = userData || {};

  return (
    <div className="profile-sidebar  w-full">
      {show_profile && (
        <>
          <div className="profile-userpic d-flex justify-content-center align-items-center activeUser">
            <img
              src={preview || image || profile}
              className="img-fluid rounded-circle"
              alt="dzital"
              style={{
                maxHeight: "120px",
                minHeight: "110px",
                maxWidth: "120px",
              }}
            />
          </div>
          <div className="profile-usertitle">
            <div className="profile-usertitle-name">{name}</div>
          </div>
        </>
      )}
      <div className="profile-userbuttons d-flex ">
        <Link
          to="/account"
          className="btn btnTheme small-text"
          style={{ background: "var(--theme-color)" }}
        >
          Personal Info
        </Link>
        <Link to="/packages?show_profile=true" className="btn btn-warning small-text">
          Upgrade to Premium
        </Link>
      </div>
      <div className="profile-usermenu">
        <ul className="nav">
          <li>
            <Link to="/add-post">
              <i className="fa fa-address-card-o" /> Add Post
            </Link>
          </li>
          <li>
            <Link to="/my-post?show_profile=true">
              <i className="fa fa-address-card-o" /> My Post
            </Link>
          </li>
          <li>
            <Link to="/cart">
              <i className="fa-solid fa-cart-shopping" /> Cart
            </Link>
          </li>
          <li>
            <Link to="/my-subscription?show_profile=true">
              <i className="fa-solid fa-check-circle" /> My Subscription
            </Link>
          </li>
          <li>
            <Link to="/my-Order?show_profile=true">
              <i className="fa fa-address-card-o" /> My Order
            </Link>
          </li>
          <li>
            <Link to="/wishlist?show_profile=true">
              <i className="fa fa-heart-o" /> Wishlist
            </Link>
          </li>
          <li>
            <Link to="/change-password?show_profile=true">
              <i className="fa fa-lock" /> Password &amp; Security
            </Link>
          </li>

          <li>
            <Link to="#" onClick={() => LogOut()}>
              <i className="fa fa-power-off" /> Sign Out
            </Link>
          </li>
        </ul>
      </div>
    </div>
  );
};

export default AccountSideBar;
