import React, { useState, useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import { useForm } from "react-hook-form";
import { Button } from "react-bootstrap";
import { useAppContext } from "../../../contextApi/AppContext";
import { toast } from "react-toastify";
import Datetime from "react-datetime";
import "react-datetime/css/react-datetime.css";
// eslint-disable-next-line
import { useLoadScript, StandaloneSearchBox } from "@react-google-maps/api";
// eslint-disable-next-line
const libraries = ["places"];

const AddProduct = ({ idDetail }) => {
  const location = useLocation();
  const {
    AddRealEstate,
    AddJob,
    AddFashionProduct,
    getAttributeList,
    attributeList,
    productId,
    AddFreelancer,
    AddElectronics,
    AddCourse,
    AddGoodsProduct,
    titleDes,
    loading,
  } = useAppContext();
  const { handleSubmit } = useForm();
  const [isImage, setIsImage] = useState(false);
  const [formData, setFormData] = useState({});
  const [formData1, setFormData1] = useState({});
  const [isChecked, setIsChecked] = useState(false);
  const [selectedOption, setSelectedOption] = useState("");
  const [amount, setAmount] = useState();
  const [propertyType, setPropertyType] = useState("");

  const handlePropertyChange = (event) => {
    setPropertyType(event.target.value);
  };

  const handleRadioChange = (value) => {
    setSelectedOption(value);
  };

  const handleAmountChange = (event) => {
    setAmount(event.target.value);
  };

  const [uploadData, setUploadData] = useState({
    image1: null,
    image2: null,
  });

  const handleImageChange = (e, imageKey) => {
    const file = e.target.files[0];
    setUploadData((prevState) => ({
      ...prevState,
      [imageKey]: file,
    }));
  };
  // eslint-disable-next-line
  const [places, setPlaces] = useState([]);
  const [center, setCenter] = useState();
  const [address, setAddress] = useState();
  const searchBoxRef = useRef(null);

  const [bidData, setBidData] = useState({
    bid_start_price: "",
    bid_entry: "",
    bid_increament_value: "",
    bid_start_date: new Date(),
    bid_end_date: new Date(),
  });

  const handlePhotoChange = (event) => {
    const file = event.target.files[0];
    setFormData({ ...formData, photo: file });
  };
  // eslint-disable-next-line
  const handleimageChange = (event) => {
    const file = event.target.files[0];
    setFormData({ ...formData, image: file });
  };

  const handleImg_1Change = (event) => {
    const file1 = event.target.files[0];
    setFormData({ ...formData, image_1: file1 });
  };

  const handleImg_2Change = (event) => {
    const file2 = event.target.files[0];
    setFormData({ ...formData, image_2: file2 });
  };

  const handleImg_3Change = (event) => {
    const file3 = event.target.files[0];
    setFormData({ ...formData, image_3: file3 });
  };

  // console.log("formData", formData);
  const handleChange = (name, value, attId) => {
    setFormData((prevData) => ({ ...prevData, [name]: value }));
    setFormData1((prevData) => ({ ...prevData, [attId]: value }));
  };

  useEffect(() => {
    const newEndDate = new Date(bidData.bid_start_date);
    newEndDate.setHours(newEndDate.getHours() + 1);
    setBidData({ ...bidData, bid_end_date: newEndDate });
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    const payloadData = {
      category_id: idDetail?.servicecategories || "",
      sub_category_id: idDetail?.subservicecat || "",
    };

    const fetchattributlist = async () => {
      await getAttributeList(payloadData);
    };
    fetchattributlist();
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    if (attributeList?.length > 0) {
      const categoryNames =
        Array.isArray(attributeList) &&
        attributeList?.map((item) => item?.category_name);
      if (
        categoryNames?.includes("Jobs") ||
        categoryNames?.includes("Freelancer") ||
        categoryNames?.includes("Lessons & Courses")
      ) {
        setIsImage(true);
      } else {
        setIsImage(false);
      }
    }
  }, [attributeList]);

  const onSubmit = async () => {
    if (isChecked) {
      if (
        !bidData.bid_start_price ||
        !bidData.bid_increament_value ||
        !bidData.bid_start_date ||
        !bidData.bid_end_date
      ) {
        toast.warning("Please fill all bid related fields.");
        // console.log("first");
        return;
      }
      if (bidData.bid_start_date >= bidData.bid_end_date) {
        toast.warning("Bid end date should be greater than bid start date.");
        return;
      }
    }

    const data1 = {
      title: titleDes?.title || "",
      description: titleDes?.description || "",
      location,

      product_id: productId,
      category_id: idDetail.servicecategories || "",
      sub_category_id: idDetail.subservicecat || "",
    };

    const dataPost = new FormData();
    if (amount && Number(amount)) {
      dataPost.append("product_price", amount || 0);
    }
    dataPost.append("purchase_mode", selectedOption || "");
    dataPost.append("lat", center?.lat || 0);
    dataPost.append("lng", center?.lng || 0);
    dataPost.append("address", address || "");
    dataPost.append("image", uploadData?.image1 || "");
    dataPost.append("company_logo", uploadData?.image2 || "");
    dataPost.append("property_type", propertyType || "");
    Object.keys(data1).forEach((key) => {
      dataPost.append(key, data1[key]);
    });

    Object.entries(formData1).forEach(([key, value], index) => {
      dataPost.append(`attributeData[${index}][attribute_id]`, key);
      dataPost.append(`attributeData[${index}][value]`, value);
    });

    if (isChecked === true) {
      dataPost.append("bid_now", true);
      dataPost.append("bid_start_price", bidData.bid_start_price || "");
      // dataPost.append('bid_entry', bidData.bid_entry || '');
      dataPost.append(
        "bid_increament_value",
        bidData.bid_increament_value || ""
      );
      const formattedStartDate = bidData.bid_start_date
        ? bidData.bid_start_date.toISOString()
        : "";
      dataPost.append("bid_start_date", formattedStartDate);

      const formattedEndDate = bidData.bid_end_date
        ? bidData.bid_end_date.toISOString()
        : "";
      dataPost.append("bid_end_date", formattedEndDate);
    }

    if (isImage === false) {
      dataPost.append("photo", formData.photo || "");
      dataPost.append("image_1", formData.image_1 || "");
      dataPost.append("image_2", formData.image_2 || "");
      dataPost.append("image_3", formData.image_3 || "");
    } else {
      dataPost.append("image", formData.image || "");
    }

    // eslint-disable-next-line
    {
      switch (attributeList[0].category_name) {
        case "Goods of all kinds":
          return AddGoodsProduct(dataPost);
        case "Fashion & Beauty":
          return AddFashionProduct(dataPost);
        case "Lessons & Courses":
          return AddCourse(dataPost);

        case "Jobs":
          return AddJob(dataPost);
        case "Freelancer":
          return AddFreelancer(dataPost);
        case "Real Estate":
          return AddRealEstate(dataPost);
        case "Electronics":
          return AddElectronics(dataPost);
        default:
          return null;
      }
    }
  };

  const handleType = (dataType) => {
    switch (dataType) {
      case "Salary Expectation":
        return "number";
      case "Typing Speed":
        return "number";
      case "Salary to":
        return "number";
      case "Salary from":
        return "number";
      case "Salary":
        return "number";
      case "Land Area":
        return "number";
      case "Price Range":
        return "number";
      case "Number of Rooms":
        return "number";
      case "Number of Bathrooms":
        return "number";
      case "Year Built":
        return "number";
      case "Square Footage":
        return "number";
      case "Rent":
        return "number";
      case "Quizzes":
        return "number";
      case "Lessons":
        return "number";
      case "Videos":
        return "number";
      case "Hours":
        return "number";
      case "Course Duration":
        return "number";
      case "Duration":
        return "number";
      case "Pack of":
        return "number";
      case "Price":
        return "number";
      case "  Model Number":
        return "number";
      case "Release Year":
        return "number";
      case "Number of Pieces":
        return "number";
      default:
        return "text";
    }
  };

  const handelEnablebid = (event) => {
    setIsChecked(event.target.checked);
  };

  const handleStartDateChange = (date) => {
    setBidData({ ...bidData, bid_start_date: date });
  };

  const handleEndDateChange = (date) => {
    if (date > bidData.bid_start_date) {
      setBidData({ ...bidData, bid_end_date: date });
    } else {
      toast.warning("End date must be after start date");
    }
  };

  const onPlacesChanged = () => {
    const places = searchBoxRef.current.getPlaces();
    if (places && places.length > 0) {
      const place = places[0];
      const newCenter = {
        lat: place.geometry.location.lat(),
        lng: place.geometry.location.lng(),
      };
      const formatted_address = place.formatted_address;
      setAddress(formatted_address);
      setCenter(newCenter);
      setPlaces(places);
    }
  };

  return (
    <section className="midBody">
      <article className="container-fluid">
        <article className="row">
          {/* right part start */}
          <div className="col-md-12">
            <div className="card">
              <div className="card-body border-0">
                <form
                  onSubmit={handleSubmit(onSubmit)}
                  encType="multipart/form-data"
                >
                  {Array.isArray(attributeList) &&
                    attributeList.map((item) => (
                      <div key={item._id} className="radioBx mb20">
                        <h6>{item.attribute}</h6>
                        <>
                          {item.options.length > 0 ? (
                            Array.isArray(item.options) &&
                            item?.options?.map((item1, index) => (
                              <React.Fragment key={item1._id}>
                                <input
                                  key={index}
                                  type="radio"
                                  className="btn-check"
                                  name={item.attribute}
                                  id={`radio_${item.attribute}_${item1._id}`}
                                  value={item1.option}
                                  onChange={(e) =>
                                    handleChange(
                                      item.attribute,
                                      e.target.value,
                                      item._id
                                    )
                                  }
                                />
                                <label
                                  className="btn btn-outline-primary"
                                  htmlFor={`radio_${item.attribute}_${item1._id}`}
                                >
                                  {" "}
                                  {item1.option}{" "}
                                </label>
                              </React.Fragment>
                            ))
                          ) : (
                            <div className="row">
                              <div key={item._id} className="">
                                <input
                                  type={handleType(item.attribute)}
                                  name={item.attribute}
                                  className="form-control"
                                  onChange={(e) =>
                                    handleChange(
                                      item.attribute,
                                      e.target.value,
                                      item._id
                                    )
                                  }
                                />
                              </div>
                            </div>
                          )}
                        </>
                      </div>
                    ))}
                  <div className="mb-3">
                    <label htmlFor="search-location" className="form-label">
                      Search Location
                    </label>
                    <StandaloneSearchBox
                      onLoad={(ref) => (searchBoxRef.current = ref)}
                      onPlacesChanged={onPlacesChanged}
                    >
                      <input
                        type="text"
                        placeholder="Search for places"
                        className="form-control"
                      />
                    </StandaloneSearchBox>
                  </div>
                  {idDetail?.servicecategories ===
                    "6548c03b1e40c887cc280d04" && (
                    <div className="form-group pb-4">
                      <label htmlFor="propertyType">Property Type:</label>
                      <select
                        id="propertyType"
                        name="propertyType"
                        className="form-control mt-2"
                        value={propertyType}
                        onChange={handlePropertyChange}
                      >
                        <option value="">Select an option</option>
                        <option value="Buy">Buy</option>
                        <option value="Rent">Rent</option>
                        <option value="Lease">Lease</option>
                      </select>
                    </div>
                  )}
                  {isImage === false ? (
                    <>
                      <div className="col-sm-3">
                        <label htmlFor="bid">
                          <h5
                            style={{
                              marginRight: "10px",
                              marginBottom: "6px",
                              color: "#77ced9",
                            }}
                          >
                            Enable Bid
                          </h5>
                        </label>
                        <input
                          type="checkbox"
                          name="bid"
                          onChange={handelEnablebid}
                        />
                      </div>

                      {isChecked && (
                        <>
                          <div className="row">
                            <div className="col-sm-3">
                              <label htmlFor="bid_start_price">
                                Bid Start Price
                              </label>
                              <input
                                className="form-control"
                                type="number"
                                name="bid_start_price"
                                onChange={(e) =>
                                  setBidData({
                                    ...bidData,
                                    bid_start_price: e.target.value,
                                  })
                                }
                              />
                            </div>
                            <div className="col-sm-3">
                              <label htmlFor="bid_increament_value">
                                Bid Increament Value
                              </label>
                              <input
                                className="form-control"
                                type="number"
                                name="bid_increament_value"
                                onChange={(e) =>
                                  setBidData({
                                    ...bidData,
                                    bid_increament_value: e.target.value,
                                  })
                                }
                              />
                            </div>
                            <div className="col-sm-3">
                              <label htmlFor="bid_start_date">
                                Bid Start Date
                              </label>
                              <Datetime
                                value={bidData.bid_start_date}
                                onChange={handleStartDateChange}
                                name="bid_start_date"
                              />
                            </div>
                            <div className="col-sm-3">
                              <label htmlFor="bid_end_date">Bid End Date</label>
                              <Datetime
                                value={bidData.bid_end_date}
                                onChange={handleEndDateChange}
                                name="bid_end_date"
                                inputProps={{ readOnly: true }} // Make input field read-only to prevent manual input
                                isValidDate={(currentDate) =>
                                  currentDate.isAfter(bidData.bid_start_date)
                                }
                              />
                            </div>
                          </div>
                        </>
                      )}

                      <h5 className="m0">UPLOAD UP TO 4 PHOTOS</h5>
                      <div className="row" style={{ maxWidth: "700px" }}>
                        {/* photo */}
                        <div className="col-sm-3">
                          <div className="fileBx mt-2">
                            <input
                              type="file"
                              name="photo"
                              id="photo"
                              style={{ display: "none" }}
                              onChange={(e) => handlePhotoChange(e)}
                            />
                            <label htmlFor="photo">
                              {formData.photo ? (
                                <img
                                  height={70}
                                  width={100}
                                  src={URL.createObjectURL(formData.photo)}
                                  alt=""
                                />
                              ) : (
                                "Upload Img"
                              )}
                            </label>
                          </div>
                        </div>
                        {/* img1 */}
                        <div className="col-sm-3">
                          <div className="fileBx mt-2">
                            <input
                              type="file"
                              name="img1"
                              id="img1"
                              style={{ display: "none" }}
                              onChange={(e) => handleImg_1Change(e)}
                            />
                            <label htmlFor="img1">
                              {formData.image_1 ? (
                                <img
                                  height={70}
                                  width={100}
                                  src={URL.createObjectURL(formData.image_1)}
                                  alt="Img_1"
                                />
                              ) : (
                                "Upload Img"
                              )}
                            </label>
                          </div>
                        </div>
                        {/* img2 */}
                        <div className="col-sm-3">
                          <div className="fileBx mt-2">
                            <input
                              type="file"
                              name="img2"
                              id="img2"
                              onChange={(e) => handleImg_2Change(e)}
                              style={{ display: "none" }}
                            />
                            <label htmlFor="img2">
                              {formData.image_2 ? (
                                <img
                                  height={70}
                                  width={100}
                                  src={URL.createObjectURL(formData.image_2)}
                                  alt="image_2"
                                />
                              ) : (
                                "Upload Img"
                              )}
                            </label>
                          </div>
                        </div>
                        {/* img3 */}
                        <div className="col-sm-3">
                          <div className="fileBx mt-2">
                            <input
                              type="file"
                              name="img3"
                              id="img3"
                              style={{ display: "none" }}
                              onChange={(e) => handleImg_3Change(e)}
                            />
                            <label htmlFor="img3">
                              {formData.image_3 ? (
                                <img
                                  height={70}
                                  width={100}
                                  src={URL.createObjectURL(formData.image_3)}
                                  alt="image_3"
                                />
                              ) : (
                                "Upload Img"
                              )}
                            </label>
                          </div>
                        </div>
                      </div>
                    </>
                  ) : (
                    <>
                      {idDetail.servicecategories ===
                        "6548c04e1e40c887cc280d07" && (
                        <>
                          <h6>Price</h6>
                          <div className="d-flex">
                            <div className="form-check ">
                              <input
                                type="radio"
                                className="btn-check"
                                name="coursePrice"
                                id="radio_coursePrice_free"
                                value="Free"
                                onChange={() => handleRadioChange("Free")}
                              />
                              <label
                                className="btn btn-outline-primary"
                                htmlFor="radio_coursePrice_free"
                              >
                                Free
                              </label>
                            </div>
                            <div className="form-check">
                              <input
                                type="radio"
                                className="btn-check"
                                name="coursePrice"
                                id="radio_coursePrice_paid"
                                value="Paid"
                                onChange={() => handleRadioChange("Paid")}
                                required
                              />
                              <label
                                className="btn btn-outline-primary"
                                htmlFor="radio_coursePrice_paid"
                              >
                                Paid
                              </label>
                            </div>
                          </div>
                          {selectedOption === "Paid" && (
                            <div className="form-group me-3 mt20 ">
                              <label htmlFor="coursePriceAmount">Amount</label>
                              <input
                                type="number"
                                className="form-control"
                                id="coursePriceAmount"
                                value={amount}
                                onChange={handleAmountChange}
                                placeholder="Enter amount"
                                required
                              />
                            </div>
                          )}
                        </>
                      )}
                      <div className="mt70">
                        <h5 className="m-0">Upload file</h5>
                        <div className="row" style={{ maxWidth: "700px" }}>
                          <div className="col-sm-3">
                            <div className="fileBx mt-2">
                              <input
                                type="file"
                                name="uploadfile1"
                                id="img1"
                                onChange={(e) => handleImageChange(e, "image1")}
                                style={{ display: "none" }}
                                required
                              />
                              <label htmlFor="img1">
                                {uploadData.image1 ? (
                                  <img
                                    height={70}
                                    width={100}
                                    src={URL.createObjectURL(uploadData.image1)}
                                    alt=""
                                  />
                                ) : (
                                  "Upload Img"
                                )}
                              </label>
                            </div>
                          </div>
                          {idDetail?.servicecategories ===
                          "6548bfec1e40c887cc280cfe" ? (
                            <>
                              <h5 className="m-0">Upload logo</h5>
                              <div className="col-sm-3">
                                <div className="fileBx mt-2">
                                  <input
                                    type="file"
                                    name="uploadfile2"
                                    id="img2"
                                    onChange={(e) =>
                                      handleImageChange(e, "image2")
                                    }
                                    style={{ display: "none" }}
                                    required
                                  />
                                  <label htmlFor="img2">
                                    {uploadData.image2 ? (
                                      <img
                                        height={70}
                                        width={100}
                                        src={URL.createObjectURL(
                                          uploadData.image2
                                        )}
                                        alt=""
                                      />
                                    ) : (
                                      "Upload Img"
                                    )}
                                  </label>
                                </div>
                              </div>
                            </>
                          ) : (
                            ""
                          )}
                        </div>
                      </div>
                    </>
                  )}
                  <Button type="submit" className="text text-white mt-2">
                    {loading ? "Submitting..." : "Submit"}
                  </Button>
                </form>
              </div>
            </div>
          </div>
        </article>
      </article>
    </section>
  );
};

export default AddProduct;
