import React, { useEffect, useState } from "react";
import Ads from "./../components/comon/Ads";
import { Link, useParams } from "react-router-dom";
import { useAppContext } from "../contextApi/AppContext";
import ShareModal from "../components/modal/ShareModal";
import { Button, Modal, Form } from "react-bootstrap";

const FreelancerDetail = ({ initialDetail }) => {
  const { id } = useParams();
  const {
    getFreelancerDetails,
    freelancerDetail,
    getReletedProduct,
    setFreelancerDetail,
    reletedList,
    sendProposal,
    productrating,
    getreviews,
    reviews,
    userData,
  } = useAppContext();
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [show, setShow] = useState(false);
  const [amount, setAmount] = useState("");
  const [message, setMessage] = useState("");

  const [rating, setRating] = useState(0);
  const [review, setReview] = useState("");
  const [images, setImages] = useState([]);
  const [previewImages, setPreviewImages] = useState([]);

  const handleRatingChange = (newRating) => {
    setRating(newRating);
    // console.log('New rating set:', rating);
  };

  const handleReviewChange = (event) => {
    setReview(event.target.value);
  };

  const handleImageChange = (event) => {
    const files = Array.from(event.target.files);
    setImages(files);
    setPreviewImages(files.map((file) => URL.createObjectURL(file)));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const formData = new FormData();
    formData.append("productId", product_id);
    formData.append("rating", rating);
    formData.append("review", review);
    images.forEach((image, index) => {
      formData.append(`attachments[${index}]`, image);
    });

    productrating(formData);
  };

  const handleClose = () => setShow(false);
  const handleShow = () => setShow(true);

  const handleSubmitpropsal = (event) => {
    event.preventDefault();
    console.log("Amount:", amount);
    console.log("Message:", message);
    const dataToSend = {
      FreelancerProductId: freelancerDetail.data._id,
      budget: amount,
      message: message,
    };
    sendProposal(dataToSend);
    handleClose();
    setMessage("");
    setAmount("");
  };

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  useEffect(() => {
    const fetchData = async () => {
      await getFreelancerDetails(id);
    };
    if (!initialDetail && id) {
      fetchData();
    }
    if (!!initialDetail && !!initialDetail.data && !!initialDetail.data._id) {
      setFreelancerDetail(initialDetail);
    }
    // eslint-disable-next-line
  }, [id, initialDetail]);

  const {
    title,
    description,
    attribute_values,
    product_id,
    createdAt,
    sub_category_id,
    category_name,
    category_id,
    category_slug,
    userId,
  } = freelancerDetail.data || {};

  useEffect(() => {
    if (product_id) {
      getreviews(product_id);
    }
  }, [product_id]);

  useEffect(() => {
    if (product_id && category_id) {
      getReletedProduct(category_id, sub_category_id, product_id);
    }
    // eslint-disable-next-line
  }, [product_id, category_id, sub_category_id]);

  const getAttributeValue = (attributeName) => {
    if (!Array.isArray(attribute_values)) return null;
    const attribute = attribute_values.find(
      (item) => item.attribute === attributeName
    );
    if (attribute) {
      return attribute.value;
    } else {
      return null;
    }
  };
  const salary = getAttributeValue("Salary");
  const location = getAttributeValue("Location");
  const experience = getAttributeValue("Experience Level");
  const industry = getAttributeValue("Industry Experience");

  const formatDuration = (createdAt) => {
    const now = new Date();
    const createdDate = new Date(createdAt);
    const diff = now - createdDate;

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

    if (days > 1) {
      return `${days} days`;
    } else {
      return `${hours} hours, ${minutes} minutes`;
    }
  };
  const formattedDuration = formatDuration(createdAt);

  console.log(userData, "user data");

  return (
    <>
      <section className="pageBanner">
        <article className="container">
          <aside className="row">
            <div className="col-md-12">
              <ul className="navList">
                <li>
                  <Link to="/">Home</Link>
                </li>
                <li>
                  <Link to={`/${category_slug}?category_id=${category_id}`}>
                    {category_name}
                  </Link>
                </li>
                <li className="active"> Detail Page of {title}</li>
              </ul>
            </div>
          </aside>
        </article>
      </section>
      <section className="midBody bgtheme">
        <article className="container-fluid">
          <article className="row">
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
            {/* right part start */}
            {freelancerDetail.isLoad && (
              <div className="col-md-10 d-flex justify-content-center ">
                <div className="spinner-grow text-info my-4" role="status">
                  <span className="sr-only">Loading...</span>
                </div>
              </div>
            )}
            {!freelancerDetail.isLoad && (
              <div className="col-md-10">
                <div className="row">
                  <div className="col-md-8">
                    <h2 className="mb-3">{title}</h2>
                  </div>
                  <div
                    className="col-md-4 d-flex gap-3 align-items-center"
                    align="right"
                  >
                    {userData._id !== userId ? (
                      <button
                        className="btn btnTheme "
                        to="#."
                        style={{ background: "var(--theme-color)" }}
                        onClick={handleShow}
                      >
                        <i className="fa fa-envelope " /> Send Proposal
                      </button>
                    ) : null}

                    <div className="iconWish">
                      <i onClick={openModal} />
                      <ShareModal isOpen={isModalOpen} onClose={closeModal} />
                    </div>
                  </div>
                </div>
                <hr />
                <div className="row">
                  <div className="col-md-8">
                    <div className="card jobeItem mb20">
                      <div className="card-body">
                        <div className="row">
                          <div className="col-md-9 col-sm-12">
                            <h5>{title}</h5>
                          </div>
                          <div className="col-md-3 col-sm-12 logoBx">
                            <img
                              src="assets/images/g-logo.png"
                              width={44}
                              className="mt5"
                              alt=""
                            />
                          </div>
                        </div>
                        <ul className="list-inline divider mb5">
                          <li>
                            <i className="fa fa-briefcase" />{" "}
                            {industry || experience || ""}
                          </li>
                          <li>
                            <i className="fa fa-inr" />{" "}
                            {salary || "Not Disclosed"}
                          </li>
                          <li>
                            <i className="fa fa-map-marker" />{" "}
                            {location || "Not Mentioned"}
                          </li>
                        </ul>
                        <hr />
                        <div className="row">
                          <div className="col-md-6">
                            <p className="mt5 mb5 text16">
                              <b>Posted :</b> {formattedDuration} ago
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                    <div className="card ">
                      <div className="card-body">
                        <h3>Description for {title}</h3>
                        <p className="mb0" align="justify">
                          {description}
                        </p>
                        <hr />
                        {Array.isArray(attribute_values) &&
                          attribute_values.map((item) => (
                            <p key={item._id}>
                              <b>{item.attribute} : </b>
                              {item.value}
                            </p>
                          ))}
                      </div>
                    </div>
                  </div>
                  <div className="col-md-4">
                    <div
                      className="card text-bg-secondery"
                      style={{ background: "var(--theme-color-dark)" }}
                    >
                      <div className="card-header">
                        <h5 className="text-light">About the Client</h5>
                      </div>
                      <ul className="list-group list-group-flush">
                        <li className="list-group-item">
                          <i className="fa fa-globe" /> <b>Country :</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            Germany
                          </span>
                        </li>
                        <li className="list-group-item">
                          <i className="fa fa-list" /> <b>Projects Paid :</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            0
                          </span>
                        </li>
                        <li className="list-group-item">
                          <i className="fa fa-pencil-square-o" />{" "}
                          <b>Projects Posted :</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            1
                          </span>
                        </li>
                        <li className="list-group-item">
                          <i className="fa fa-thumbs-o-up" />{" "}
                          <b>Total Feedbacks :</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            1
                          </span>
                        </li>
                        <li className="list-group-item">
                          <i className="fa fa-thumbs-o-up" /> <b>Feedbacks :</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            1
                          </span>
                        </li>
                        <li className="list-group-item">
                          <i className="fa fa-cubes" /> <b>Total Spent :</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            ₹ 0
                          </span>
                        </li>
                        <li className="list-group-item">
                          <i className="fa fa-users" /> <b>Client Type</b>{" "}
                          <span className="badge bg-primary rounded-pill float-end">
                            Company
                          </span>
                        </li>
                      </ul>
                      <div className="card-footer text-light">
                        Member since 15 Nov, 2023
                      </div>
                    </div>
                  </div>
                </div>

                <div className="col-md-12 mt10">
                  <div className="card">
                    <div className="card-header">
                      <h4>Rate this product:</h4>
                    </div>
                    <div className="card-body">
                      <div className="rating mt-4">
                        {[...Array(5)].map((star, index) => (
                          <button
                            key={index}
                            type="button"
                            className={`btn btn-link ${
                              index < rating ? "text-warning" : ""
                            }`}
                            onClick={() => handleRatingChange(index + 1)}
                          >
                            <i className="fas fa-star"></i>
                          </button>
                        ))}
                      </div>
                      <form onSubmit={handleSubmit} className="mt-4">
                        <div className="form-group">
                          <label htmlFor="review">Review:</label>
                          <textarea
                            id="review"
                            className="form-control"
                            value={review}
                            onChange={handleReviewChange}
                          ></textarea>
                        </div>
                        <div className="form-group mt-3">
                          <label htmlFor="images">Upload Images:</label>
                          <input
                            type="file"
                            id="images"
                            className="form-control"
                            multiple
                            onChange={handleImageChange}
                          />
                          <div className="preview-images mt-3">
                            {previewImages.map((src, index) => (
                              <img
                                key={index}
                                src={src}
                                alt="Preview"
                                className="img-thumbnail mr-2"
                                style={{ width: "100px", height: "100px" }}
                              />
                            ))}
                          </div>
                        </div>
                        <button type="submit" className="btn btn-primary mt-3">
                          Submit Review
                        </button>
                      </form>
                    </div>
                  </div>

                  {Array.isArray(reviews?.data) && reviews?.data ? (
                    <div className="mt-5">
                      <h4>Reviews:</h4>
                      {Array.isArray(reviews.data) &&
                        reviews?.data?.map((review) => (
                          <div className="card mb-3 shadow-sm" key={review._id}>
                            <div className="card-body">
                              <div className="d-flex align-items-center mb-3">
                                <img
                                  src={review.user_img}
                                  alt="User"
                                  className="rounded-circle mr-3"
                                  style={{ width: "50px", height: "50px" }}
                                />
                                <div>
                                  <div
                                    className="user-pofileinfo"
                                    style={{ marginLeft: "10px" }}
                                  >
                                    <h6 className="mb-0">{review.user_name}</h6>
                                    <small className="text-muted">
                                      {new Date(
                                        review.createdAt
                                      ).toLocaleDateString()}
                                    </small>
                                  </div>
                                </div>
                              </div>
                              <div className="rating">
                                {[...Array(5)].map((star, index) => (
                                  <i
                                    key={index}
                                    className={`fas fa-star ${
                                      index < review.rating
                                        ? "text-warning"
                                        : "text-secondary"
                                    }`}
                                  ></i>
                                ))}
                              </div>
                              <p className="mt-3">{review.review}</p>
                              <div className="mt-3">
                                {review.attachments.map((src, index) => (
                                  <img
                                    key={index}
                                    src={src}
                                    alt="Review attachment"
                                    className="img-thumbnail mr-2 mb-2"
                                    style={{ width: "100px", height: "100px" }}
                                  />
                                ))}
                              </div>
                            </div>
                          </div>
                        ))}
                    </div>
                  ) : (
                    <div> No Reviws Found</div>
                  )}
                </div>

                <div className="row">
                  <div className="col-md-12">
                    <h5 className="mt-3">Related Field</h5>
                    <hr className="mt0" />
                  </div>
                  {/* item start */}
                  {Array.isArray(reletedList) &&
                    reletedList.map((item) => {
                      const formatDuration = (createdAt) => {
                        const now = new Date();
                        const createdDate = new Date(createdAt);
                        const diff = now - createdDate;

                        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
                        const hours = Math.floor(
                          (diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)
                        );
                        const minutes = Math.floor(
                          (diff % (1000 * 60 * 60)) / (1000 * 60)
                        );

                        if (days > 1) {
                          return `${days} days`;
                        } else {
                          return `${hours} hours, ${minutes} minutes`;
                        }
                      };
                      const formattedDuration = formatDuration(item.createdAt);
                      return (
                        <div className="col-md-6" key={item._id}>
                          <div className="card mb-3" style={{ maxWidth: 540 }}>
                            <div className="row g-0">
                              <Link
                                to={`/product/related-product/${item._id}`}
                                className="col-md-4"
                              >
                                <img
                                  src={item.image}
                                  className="img-fluid rounded-start"
                                  style={{ height: "100%" }}
                                  alt="..."
                                />
                              </Link>
                              <div className="col-md-8">
                                <div className="card-body">
                                  <h5 className="card-title">{item.title}</h5>
                                  <p
                                    style={{
                                      overflow: "hidden",
                                      textOverflow: "ellipsis",
                                      display: "-webkit-box",
                                      WebkitLineClamp: 2,
                                      WebkitBoxOrient: "vertical",
                                    }}
                                  >
                                    {item.description}
                                  </p>
                                  <p className="card-text">
                                    <small className="text-body-secondary">
                                      Posted: {formattedDuration}
                                    </small>
                                  </p>
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  {/* item end */}
                </div>
              </div>
            )}
            {/* right part end */}
            {/* ad box start */}
            <Ads />
            {/* ad box end */}
          </article>
        </article>

        <Modal show={show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title>Send Proposal</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form onSubmit={handleSubmitpropsal}>
              <Form.Group controlId="formAmount">
                <Form.Label>Amount</Form.Label>
                <Form.Control
                  type="number"
                  placeholder="Enter amount"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                />
              </Form.Group>

              <Form.Group controlId="formMessage">
                <Form.Label>Message</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  placeholder="Enter message"
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                />
              </Form.Group>

              <Button
                variant="primary"
                type="submit"
                style={{ marginTop: "10px" }}
              >
                Submit
              </Button>
            </Form>
          </Modal.Body>
        </Modal>
      </section>
    </>
  );
};

export default FreelancerDetail;
