import React from 'react';
import { FaShareAlt, FaFacebook, FaTwitter, FaLinkedin, FaWhatsapp } from 'react-icons/fa';
import 'bootstrap/dist/css/bootstrap.min.css';

const ShareModal = ({ isOpen, onClose, onOpenModal }) => {
  const currentPageUrl = window.location.href;
  const currentTitle = encodeURIComponent(document.title);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(currentPageUrl)
      .then(() => {
        alert('Link copied to clipboard!');
      })
      .catch((error) => {
        console.error('Failed to copy link to clipboard:', error);
      });
  };

  const socialMediaLinks = {
    facebook: `https://www.facebook.com/sharer/sharer.php?u=${currentPageUrl}`,
    twitter: `https://twitter.com/intent/tweet?url=${currentPageUrl}&text=${currentTitle}`,
    linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${currentPageUrl}`,
    whatsapp: `https://api.whatsapp.com/send?text=${currentPageUrl}`,
  };

  return (
    <div className={`modal fade ${isOpen ? 'show' : ''}`} tabIndex="-1" role="dialog" style={{ display: isOpen ? 'block' : 'none' }}>
      <div className="modal-dialog" role="document">
        <div className="modal-content">
          <div className="modal-header bg-primary text-white">
            <h5 className="modal-title">Share This Page</h5>
            <button type="button" className="close text-white" onClick={onClose} aria-label="Close">
              <span aria-hidden="true">&times;</span>
            </button>
          </div>
          <div className="modal-body">
            <p>Share this link:</p>
            <div className="input-group mb-3">
              <input type="text" className="form-control" value={currentPageUrl} readOnly />
              <div className="input-group-append">
                <button className="btn btn-outline-secondary" onClick={handleCopyLink} type="button">
                  Copy
                </button>
              </div>
            </div>
            <p>Share on:</p>
            <div className="d-flex justify-content-around">
              <a href={socialMediaLinks.facebook} className="btn btn-outline-primary" target="_blank" rel="noopener noreferrer" aria-label="Share on Facebook">
                <FaFacebook />
              </a>
              <a href={socialMediaLinks.twitter} className="btn btn-outline-info" target="_blank" rel="noopener noreferrer" aria-label="Share on Twitter">
                <FaTwitter />
              </a>
              <a href={socialMediaLinks.linkedin} className="btn btn-outline-primary" target="_blank" rel="noopener noreferrer" aria-label="Share on LinkedIn">
                <FaLinkedin />
              </a>
              <a href={socialMediaLinks.whatsapp} className="btn btn-outline-success" target="_blank" rel="noopener noreferrer" aria-label="Share on WhatsApp">
                <FaWhatsapp />
              </a>
            </div>
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose}>
              Close
            </button>
          </div>
        </div>
      </div>
      <div className="position-fixed" style={{ bottom: '20px', right: '20px' }}>
        <button className="btn btn-primary btn-lg rounded-circle" onClick={onOpenModal} aria-label="Share">
          <FaShareAlt />
        </button>
      </div>
    </div>
  );
};

export default ShareModal;
