import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useAppContext } from "../../../contextApi/AppContext";
import NoData from "../../noData/NoData";

const CartList = () => {
  const { cartList, getCartList, cartListRemove, cartListUpdate, totalprice, orderCheckOut } =
    useAppContext();
  const [quantities, setQuantities] = useState({});

  useEffect(() => {
    const fetchCartList = async () => {
      await getCartList();
    };
    fetchCartList();
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    const initialQuantities = cartList.reduce((acc, item) => {
      acc[item.item_details._id] = item.quantity;
      return acc;
    }, {});
    setQuantities(initialQuantities);
  }, [cartList]);

  const increaseQuantity = (id) => {
    const updatedQuantity = (quantities[id] || 0) + 1;
    setQuantities((prevQuantities) => ({
      ...prevQuantities,
      [id]: updatedQuantity,
    }));
    cartListUpdate(id, updatedQuantity);
  };

  const decreaseQuantity = (id) => {
    if (quantities[id] > 0) {
      const updatedQuantity = quantities[id] - 1;
      setQuantities((prevQuantities) => ({
        ...prevQuantities,
        [id]: updatedQuantity,
      }));
      cartListUpdate(id, updatedQuantity);
    }
  };

  const handleDelete = (id) => {
    cartListRemove(id);
  };

  const handleCheckOut = async () => {
    const data = cartList.map((item) => {
      return {
        product_id: item.item_details?._id,
        quantity: item.quantity,
        total_price: item.total_price
      }
    });
    const body = { total_price: totalprice, items: data };
    await orderCheckOut(body, data.product_id);
  };

  return (


    <section className="h-100" style={{ backgroundColor: "#eee" }}>
      <div className="container">
      <h5 className="fw-normal mb-0 text-black pt-2 pb-2">Shopping Cart</h5>
      <div style={{height:'81vh'}}>
        <div className="row justify-content-center align-items-center h-100">
          <div className="col-md-10">
          
            {cartList.length === 0 ? (
              <NoData
                des={"Kindly add the product to your checkout. Thank you!"}
              />
            ) : (
              Array.isArray(cartList) &&
              cartList.map((item) => {
                const price = item.total_price / item.quantity;

                return (
                  <div className="card rounded-3 mb-4" key={item.item_details._id}>
                    <div className="card-body p-4">
                      <div className="row justify-content-between align-items-center">
                        <div className="col-md-2">
                          <Link to={`/product/related-product/${item.item_details._id}`}>
                            <img
                              className="img-fluid rounded-3"
                              src={item.item_details.image}
                              alt={item.item_details.title}
                              style={{ height: "170px", width: "200px" }}
                            />
                          </Link>
                        </div>
                        <div className="col-md-3">
                          <p className="lead fw-normal mb-2">
                            {item.item_details.title}
                          </p>
                        </div>
                        <div className="col">
                          <p className="fw-normal mb-2">{price}</p>
                        </div>
                        <div className="col-md-3 d-flex align-items-center justify-content-around">
                          <button
                            onClick={() => decreaseQuantity(item.item_details._id)}
                            className="btn btn-outline-primary btn-sm"
                          >
                            -
                          </button>
                          <input
                            value={quantities[item.item_details._id] || ""}
                            type="number"
                            className="form-control form-control-sm"
                            onChange={() => { }}
                            style={{ width: "60px", textAlign: "center" }}
                          />
                          <button
                            className="btn btn-outline-primary btn-sm"
                            onClick={() => increaseQuantity(item.item_details._id)}
                          >
                            +
                          </button>
                        </div>
                        <div className="col-md-2">
                          <h5 className="mb-0">
                            ₹ {quantities[item.item_details._id] * price || item.total_price}
                          </h5>
                        </div>
                        <div className="col-md-1 text-end">
                          <button
                            className="btn btn-danger btn-sm"
                            onClick={() => handleDelete(item.item_details._id)}
                          >
                            <i className="fas fa-trash"></i>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            {cartList.length ? (
              <div className="col-md-12 col-lg-4">
                <div className="bg-light p-3">
                  <h3 className="mb-4">Summary</h3>
                  <div className="d-flex justify-content-between mb-2">
                    <span>Total</span>
                    <span className="price"> ₹ {totalprice}</span>
                  </div>
                  <button
                    type="button"
                    className="btn btn-primary btn-lg btn-block mt-3 text-white"
                    onClick={handleCheckOut}
                  >
                    Checkout
                  </button>
                </div>
              </div>
            ) : null}
          </div>
        </div>
        </div>
      </div>
    </section>
  );
};

export default CartList;
